  3068  CheckedError Parser::ParseFlexBufferValue(flexbuffers::Builder *builder) {
  3069    ParseDepthGuard depth_guard(this);
  3070    ECHECK(depth_guard.Check());
  3071
  3072    switch (token_) {
  3073      case '{': {
  3074        auto start = builder->StartMap();
  3075        size_t fieldn_outer = 0;
  3076        auto err =
  3077            ParseTableDelimiters(fieldn_outer, nullptr,
  3078                                 [&](const std::string &name, size_t &fieldn,
  3079                                     const StructDef *) -> CheckedError {
  3080                                   builder->Key(name);
  3081                                   ECHECK(ParseFlexBufferValue(builder));
  3082                                   fieldn++;
  3083                                   return NoError();
  3084                                 });
  3085        ECHECK(err);
  3086        builder->EndMap(start);
  3087        if (builder->HasDuplicateKeys())
  3088          return Error("FlexBuffers map has duplicate keys");
  3089        break;
  3090      }
  3091      case '[': {
  3092        auto start = builder->StartVector();
  3093        uoffset_t count = 0;
  3094        ECHECK(ParseVectorDelimiters(count, [&](uoffset_t &) -> CheckedError {
  3095          return ParseFlexBufferValue(builder);
  3096        }));
  3097        builder->EndVector(start, false, false);
  3098        break;
  3099      }
  3100      case kTokenStringConstant:
  3101        builder->String(attribute_);
  3102        EXPECT(kTokenStringConstant);
  3103        break;
  3104      case kTokenIntegerConstant:
  3105        builder->Int(StringToInt(attribute_.c_str()));
  3106        EXPECT(kTokenIntegerConstant);
  3107        break;
  3108      case kTokenFloatConstant: {
  3109        double d;
  3110        StringToNumber(attribute_.c_str(), &d);
  3111        builder->Double(d);
  3112        EXPECT(kTokenFloatConstant);
  3113        break;
  3114      }
  3115      case '-':
  3116      case '+': {
  3117        // `[-+]?(nan|inf|infinity)`, see ParseSingleValue().
  3118        const auto sign = static_cast<char>(token_);
  3119        NEXT();
  3120        if (token_ != kTokenIdentifier)
  3121          return Error("floating-point constant expected");
  3122        attribute_.insert(0, 1, sign);
  3123        ECHECK(ParseFlexBufferNumericConstant(builder));
  3124        NEXT();
  3125        break;
  3126      }
  3127      default:
  3128        if (IsIdent("true")) {
  3129          builder->Bool(true);
  3130          NEXT();
  3131        } else if (IsIdent("false")) {
  3132          builder->Bool(false);
  3133          NEXT();
  3134        } else if (IsIdent("null")) {
  3135          builder->Null();
  3136          NEXT();
  3137        } else if (IsIdent("inf") || IsIdent("infinity") || IsIdent("nan")) {
  3138          ECHECK(ParseFlexBufferNumericConstant(builder));
  3139          NEXT();
  3140        } else
  3141          return TokenError();
  3142    }
  3143    return NoError();
  3144  }
