  1772    bool VerifyRef(Reference r) {
  1773      // r.parent_width_ and r.data_ already verified.
  1774      if (!VerifyByteWidth(r.byte_width_) || !VerifyType(r.type_)) {
  1775        return false;
  1776      }
  1777      if (IsInline(r.type_)) {
  1778        // Inline scalars, don't require further verification.
  1779        return true;
  1780      }
  1781      // All remaining types are an offset.
  1782      auto off = ReadUInt64(r.data_, r.parent_width_);
  1783      if (!VerifyOffset(off, r.data_))
  1784        return false;
  1785      auto p = r.Indirect();
  1786      switch (r.type_) {
  1787        case FBT_INDIRECT_INT:
  1788        case FBT_INDIRECT_UINT:
  1789        case FBT_INDIRECT_FLOAT:
  1790          return VerifyFromPointer(p, r.byte_width_);
  1791        case FBT_KEY:
  1792          return VerifyKey(p);
  1793        case FBT_MAP:
  1794          return VerifyVector(p, FBT_NULL, r.byte_width_, r.byte_width_) &&
  1795                 VerifyKeys(p, r.byte_width_);
  1796        case FBT_VECTOR:
  1797          return VerifyVector(p, FBT_NULL, r.byte_width_, r.byte_width_);
  1798        case FBT_VECTOR_INT:
  1799          return VerifyVector(p, FBT_INT, r.byte_width_, r.byte_width_);
  1800        case FBT_VECTOR_BOOL:
