  1803        case FBT_VECTOR_FLOAT:
  1804          return VerifyVector(p, FBT_FLOAT, r.byte_width_, r.byte_width_);
  1805        case FBT_VECTOR_KEY:
  1806          return VerifyVector(p, FBT_KEY, r.byte_width_, r.byte_width_);
  1807        case FBT_VECTOR_STRING_DEPRECATED:
  1808          // Use of FBT_KEY here intentional, see elsewhere.
  1809          return VerifyVector(p, FBT_KEY, r.byte_width_, r.byte_width_);
  1810        case FBT_BLOB:
  1811          return VerifyVector(p, FBT_UINT, r.byte_width_, 1);
  1812        case FBT_STRING:
  1813          return VerifyVector(p, FBT_UINT, r.byte_width_, 1) &&
  1814                 VerifyTerminator(String(p, r.byte_width_));
  1815        case FBT_VECTOR_INT2:
  1816        case FBT_VECTOR_UINT2:
  1817        case FBT_VECTOR_FLOAT2:
  1818        case FBT_VECTOR_INT3:
  1819        case FBT_VECTOR_UINT3:
  1820        case FBT_VECTOR_FLOAT3:
  1821        case FBT_VECTOR_INT4:
  1822        case FBT_VECTOR_UINT4:
  1823        case FBT_VECTOR_FLOAT4: {
  1824          uint8_t len = 0;
  1825          auto vtype = ToFixedTypedVectorElementType(r.type_, &len);
  1826          if (!VerifyType(vtype))
  1827            return false;
  1828          return VerifyFromPointer(p, r.byte_width_ * len);
  1829        }
  1830        default:
  1831          return false;
  1832      }
  1833    }
  1834
  1835   public:
  1836    bool VerifyBuffer() {
  1837      if (!Check(size_ >= 3)) return false;
  1838      auto end = buf_ + size_;
  1839      auto byte_width = *--end;
  1840      auto packed_type = *--end;
  1841      return VerifyByteWidth(byte_width) &&
  1842             Check(end - buf_ >= byte_width) &&
  1843             VerifyRef(Reference(end - byte_width, byte_width, packed_type));
  1844    }
  1845
  1846   private:
  1847    const uint8_t *buf_;
  1848    size_t size_;
  1849    std::vector<bool> *reuse_tracker_;
  1850  };
  1851
  1852  // Utility function that contructs the Verifier for you, see above for parameters.
  1853  inline bool VerifyBuffer(const uint8_t *buf, size_t buf_len, std::vector<bool> *reuse_tracker) {
  1854    Verifier verifier(buf, buf_len, reuse_tracker);
  1855    return verifier.VerifyBuffer();
  1856  }
