  1861  // FlatBuffers verifier, which should only be present if flatbuffer.h
  1862  // has been included (which it typically is in generated code).
  1863  inline bool VerifyNestedFlexBuffer(const flatbuffers::Vector<uint8_t> *nv,
  1864                                     flatbuffers::Verifier &verifier) {
  1865    if (!nv) return true;
  1866    return verifier.Check(
  1867      flexbuffers::VerifyBuffer(nv->data(), nv->size(),
  1868                                &verifier.GetReuseVector()));
